static std::once_flag flag;
static std::unique_ptr<Hardware> inst;

Hardware& Hardware::instance() {
    std::call_once(flag, [] { inst.reset(new Hardware(probe())); });
    return *inst;
}

static Config* inst = 0;
static Mutex mtx;

Config& Config::instance() {
    Guard g(mtx);              // lock on every access: correct, just slower
    if (!inst) inst = new Config;
    return *inst;
}
// pthread_once(&once, init) or ACE_Singleton<Config, ACE_Null_Mutex> are the library
// forms; DCLP (test, lock, test, store) is not reliable.
